import json,pathlib,collections
R=pathlib.Path(__file__).resolve().parents[1];N=R.name=='T-008';RUN=R/'runs/run-001'
def read(n):return json.loads((RUN/(n+'.json')).read_text(encoding='utf-8'))
def save(n,x):(RUN/(n+'.json')).write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
summary=read('summary');cells=read('cells');files=read('proposed_files');manifest=read('manifest')
claims={'source':'sources/FSE2023_Nezha.pdf §5.1 p8' if N else 'sources/paper.html §V-A, §V-E','authors':['Guangba Yu','Pengfei Chen','Yufeng Li','Hongyang Chen','Xiaoyun Li','Zibin Zheng'] if N else ['Cheryl Lee','Tianyi Yang','Zhuangbin Chen','Yuxin Su','Michael R. Lyu'],'year':2023,'reported_injections':{'OB':56,'TT':45} if N else {'TT':162,'SN':72},'reported_normal_hours':{} if N else {'TT':7,'SN':1.2},'fault_duration_seconds':{'OB':180,'TT':180} if N else {'TT':600,'SN':120},'reported_resource_code':{'OB':{'resource':42,'code':14},'TT':{'resource':20,'code':25}} if N else {},'stack':'OpenTelemetry SDK/Collector → Tempo; Promtail → Loki; cAdvisor + Istio + Node Exporter → Prometheus' if N else 'Jaeger; cAdvisor + Prometheus → InfluxDB; Fluentd, Elasticsearch, Kibana','injection':'Code: Java Byteman, Python Hypno, Go Failpoint (refs 4/28/52). CPU/network tool cụ thể OPEN trong đoạn nguồn đã kiểm.' if N else 'Chaosblade: CPU exhaustion, network jam, packet loss','kind':'FACT nguồn công bố, không phải kiểm telemetry'}
